  var BANDAGE = "hospital/bandage";
  var RAIN = 'weather/rainy';
  /*DATA-END*/

  var LOCALES = ['en', 'de', 'nl', 'da', 'sv', 'no', 'es', 'it', 'pt', 'fr', 'fi'];
  var TASKS = ['name', 'trouble', 'fix', 'match'];
  var ROLES = ['start', 'trouble', 'fix'];
  var KINDS = ['start', 'trouble', 'fix', 'tcalm', 'tother', 'fother', 'fsame'];
  /* the three ways the loose pages can lie in Name the parts so that place never tells the part: each one keeps exactly one page
     in its story place and swaps the other two — over a pass every table place holds every part three times, and the story order never appears */
  var NAME_ARR = [[0, 2, 1], [2, 1, 0], [1, 0, 2]];

  function locale(l) { l = String(l || 'en').slice(0, 2); return TEXT[l] ? l : 'en'; }
  function clone(o) { return JSON.parse(JSON.stringify(o)); }

  /* ---------------- the pages ---------------- */
  /* what goes wrong on a page (the coral ring) — on a "different trouble" page it is that trouble (the rain, or the basket the crow takes) */
  function thingOf(story, kind) {
    var P = STORIES[story].pages[kind];
    if (P.th) return P.th;
    if (kind === 'tother') { for (var i = 0; i < P.t.length; i++) if (P.t[i][0] === RAIN) return RAIN; }
    var th = STORIES[story].thing;
    if (th === 'sky') { for (var j = 0; j < P.t.length; j++) if (/^weather\//.test(P.t[j][0])) return P.t[j][0]; }
    return th;
  }
  function pageOf(loc, story, kind) {
    loc = locale(loc);
    var P = STORIES[story].pages[kind];
    return { id: story + '-' + kind, story: story, kind: kind, t: clone(P.t), d: clone(P.d || {}), thing: thingOf(story, kind), caption: TEXT[loc].c[story][kind] };
  }
  /* the page's behaviour when the book reads it */
  function cracks(kind) { return kind === 'trouble' || kind === 'tother'; }
  function sendsBandage(kind) { return kind === 'fix' || kind === 'fother'; }
  function mends(fixKind, troubleKind) { return fixKind === 'fix' && troubleKind === 'trouble'; }

